source:
\begin{lem}\ollabel{ordmemberord}
Every !!{element} of an ordinal is an ordinal.
\end{lem}

target:
\begin{lem}\ollabel{ordmemberord}
د ترتيبي عدد هر !!{element} ترتيبي عدد دے.
\end{lem}

source:
\begin{cor}\ollabel{ordissetofsmallerord}
$\alpha = \Setabs{\beta \in \alpha}{\beta \text{ is an ordinal}}$, for
any ordinal~$\alpha$
\end{cor}

target:
\begin{cor}\ollabel{ordissetofsmallerord}
$\alpha = \Setabs{\beta \in \alpha}{\beta \text{ ترتيبي عدد دے}}$، د
هر ترتيبي عدد~$\alpha$ دپاره.
\end{cor}

source:
\begin{proof}
Immediate from \olref{ordmemberord}.
\end{proof}

target:
\begin{proof}
له \olref{ordmemberord} څخه سمدستي نتيجه اخلو.
\end{proof}

source:
\begin{thm}[Trichotomy]\ollabel{ordtrichotomy} 
$\alpha \in \beta \lor \alpha = \beta \lor \beta \in \alpha$, for any
ordinals $\alpha$ and $\beta$. 
\end{thm}

target:
\begin{thm}[درې ګونتوب]\ollabel{ordtrichotomy}
$\alpha \in \beta \lor \alpha = \beta \lor \beta \in \alpha$، د هر دوو
ترتيبي عددونو $\alpha$ او $\beta$ دپاره.
\end{thm}

source:
\begin{proof}
The proof is by double induction, i.e., using
\olref{ordinductionschema} twice. Say that $x$ is \emph{comparable}
with $y$ iff $x \in y \lor x = y \lor y \in x$.

\begin{proof}
Just like \olref[wo]{wo:strictorder}.
\end{proof}

target:
\begin{proof}
د \olref[wo]{wo:strictorder} په شان.
\end{proof}

source:
\begin{prob}
Complete the ``exactly similar reasoning'' in the proof of
\olref[sth][ordinals][basic]{ordtrichotomy}.
\end{prob}

target:
\begin{prob}
د \olref[sth][ordinals][basic]{ordtrichotomy} په ثبوت کښې «په عين ورته
استدلال» بشپړ کړئ.
\end{prob}

source:
\begin{cor}\ollabel{corordtransitiveord}
$A$ is an ordinal iff $A$ is a transitive set of ordinals.
\end{cor}

target:
\begin{cor}\ollabel{corordtransitiveord}
$A$ ترتيبي عدد دے، که او يوازې که $A$ د ترتيبي عددونو متعدي سټ وي.
\end{cor}

source:
\begin{proof}
\emph{Left-to-right.} By \olref{ordmemberord}. \emph{Right-to-left.}
If $A$ is a transitive set of ordinals, then $\in$ well-orders $A$ by
\olref{ordinductionschema} and \olref{ordtrichotomy}.
\end{proof}

target:
\begin{proof}
\emph{له چپ نه ښي خوا ته.} د \olref{ordmemberord} له مخې.
\emph{له ښي نه چپ خوا ته.} که $A$ د ترتيبي عددونو متعدي سټ وي، نو
$\in$ د $A$ ښه ترتيب د \olref{ordinductionschema} او
\olref{ordtrichotomy} له مخې ورکوي.
\end{proof}

source:
\begin{thm}[Burali-Forti Paradox]\ollabel{buraliforti}
There is no set of all the ordinals
\end{thm}

target:
\begin{thm}[د بورالي--فورتي تناقض]\ollabel{buraliforti}
د ټولو ترتيبي عددونو سټ نشته.
\end{thm}

source:
\begin{prop}
Any strictly descending sequence of ordinals is finite.
\end{prop}

target:
\begin{prop}
د ترتيبي عددونو هره په کلکه نزولي لړۍ متناهي ده.
\end{prop}

source:
\begin{proof}
Any infinite strictly descending sequence of ordinals $\alpha_0 > \alpha_1 > \alpha_2 > \ldots$ has no $<$-minimal
member, contradicting \olref{ordinductionschema}.
\end{proof}

target:
\begin{proof}
د ترتيبي عددونو هره نامتناهي په کلکه نزولي لړۍ $\alpha_0 > \alpha_1 > \alpha_2 > \ldots$
د $<$ له مخې مينيمال غړے نۀ لري، چې له \olref{ordinductionschema} سره
په تناقض کښې ده.
\end{proof}

source:
\begin{prop}\ollabel{ordinalsaresubsets}
$\alpha \subseteq \beta \lor \beta \subseteq \alpha$, for any ordinals
$\alpha, \beta$.
\end{prop}

target:
\begin{prop}\ollabel{ordinalsaresubsets}
$\alpha \subseteq \beta \lor \beta \subseteq \alpha$، د هر دوو ترتيبي
عددونو $\alpha, \beta$ دپاره.
\end{prop}

source:
\begin{proof}
If $\alpha \in \beta$, then $\alpha \subseteq \beta$ as $\beta$ is
transitive. Similarly, if $\beta \in \alpha$, then $\beta \subseteq
\alpha$. And if $\alpha = \beta$, then $\alpha \subseteq \beta$ and
$\beta \subseteq \alpha$. So by   \olref{ordtrichotomy} we are done.
\end{proof}

target:
\begin{proof}
که $\alpha \in \beta$ وي، نو $\alpha \subseteq \beta$ دے، ځکه چې $\beta$
متعدي دے. همدارنګه، که $\beta \in \alpha$ وي، نو $\beta \subseteq
\alpha$ دے. او که $\alpha = \beta$ وي، نو $\alpha \subseteq \beta$ او
$\beta \subseteq \alpha$ دي. نو د \olref{ordtrichotomy} له مخې مقصد ترلاسه شو.
\end{proof}

source:
\begin{prop}\ollabel{ordisoidentity}
$\alpha = \beta$ iff $\ordeq{\alpha}{\beta}$, for any ordinals
$\alpha, \beta$.
\end{prop}

target:
\begin{prop}\ollabel{ordisoidentity}
$\alpha = \beta$، که او يوازې که $\ordeq{\alpha}{\beta}$ وي، د هر دوو
ترتيبي عددونو $\alpha, \beta$ دپاره.
\end{prop}

source:
\begin{proof}
The ordinals are well-orders; so this is immediate from Trichotomy
(\olref[basic]{ordtrichotomy}) and
\olref[iso]{wellordnotinitial}. 
\end{proof}

target:
\begin{proof}
ترتيبي عددونه ښه ترتيبونه دي؛ نو دا له درې ګونتوب
(\olref[basic]{ordtrichotomy}) او
\olref[iso]{wellordnotinitial} څخه سمدستي نتيجه اخلو.
\end{proof}

source:
\begin{prob}\ollabel{probunionordinalsordinal}
Prove that, if every member of $X$ is an ordinal, then $\bigcup X$ is an ordinal.
\end{prob}

target:
\begin{prob}\ollabel{probunionordinalsordinal}
ثابت کړئ چې، که د $X$ هر غړے ترتيبي عدد وي، نو $\bigcup X$ ترتيبي عدد دے.
\end{prob}

