source:
\begin{thm}\ollabel{thmOrdinalRepresentation}
Every well-ordering is isomorphic to a unique ordinal. 
\end{thm}

target:
\begin{thm}\ollabel{thmOrdinalRepresentation}
هر ښه ترتيب له يوه يوازيني ترتيبي عدد سره آيزومورف دے.
\end{thm}

source:
\begin{defn}
If $\tuple{A, <}$ is a well-ordering, then its order type,
$\ordtype{A, <}$, is the unique ordinal $\alpha$ such that
$\ordeq{\tuple{A, < }}{\alpha}$.
\end{defn}

target:
\begin{defn}
که $\tuple{A, <}$ ښه ترتيب وي، نو د هغه د ترتيب ډول،
$\ordtype{A, <}$، هغه يوازينے ترتيبي عدد $\alpha$ دے چې
$\ordeq{\tuple{A, < }}{\alpha}$ وي.
\end{defn}

source:
\begin{cor}\ollabel{ordtypesworklikeyouwant}
Where $\tuple{A, <}$ and $\tuple{B, \lessdot}$ are well-orderings: 
\begin{align*}
	\ordtype{A, <} = \ordtype{B, \lessdot}&\text{ iff }\ordeq{\tuple{A, <}}{\tuple{B, \lessdot}}\\
	\ordtype{A, <} \in \ordtype{B, \lessdot}&\text{ iff }\ordeq{\tuple{A, <}}{\tuple{B_b, \lessdot_b}}\text{ for some }b \in B
\end{align*}
\end{cor}

target:
\begin{cor}\ollabel{ordtypesworklikeyouwant}
که $\tuple{A, <}$ او $\tuple{B, \lessdot}$ ښه ترتيبونه وي:
\begin{align*}
	\ordtype{A, <} = \ordtype{B, \lessdot}&\text{ هله او يوازې هله چې }\ordeq{\tuple{A, <}}{\tuple{B, \lessdot}}\\
	\ordtype{A, <} \in \ordtype{B, \lessdot}&\text{ هله او يوازې هله چې }\ordeq{\tuple{A, <}}{\tuple{B_b, \lessdot_b}}\text{ د يو مناسب }b \in B
\end{align*}
\end{cor}

source:
\begin{proof}
The identity holds by \olref[basic]{ordisoidentity}. To prove
the second claim, let $\ordtype{A, <} = \alpha$ and $\ordtype{B,
\lessdot} = \beta$, and let $f \colon \beta \to \tuple {B, \lessdot}$
be our isomorphism. Then:
\begin{align*}
	\alpha \in \beta&\text{ iff }\funrestrictionto{f}{\alpha} \colon \alpha \to B_{f(\alpha)}\text{ is an isomorphism}\\
	&\text{ iff }\ordeq{\tuple{A, <}}{\tuple{B_{f(\alpha)}, \lessdot_{f(\alpha)}}}\\
	&\text{ iff }\ordeq{\tuple{A, <}}{\tuple{B_b, \lessdot_b}}\text{ for some $b \in B$}
\end{align*}
by \olref[iso]{ordisounique},
\olref[iso]{wellordinitialsegment}, and
\olref[basic]{ordissetofsmallerord}.
\end{proof}

target:
\begin{proof}
برابري د \olref[basic]{ordisoidentity} له مخې ده. د دويمې ادعا د
ثابتولو دپاره، $\ordtype{A, <} = \alpha$ او $\ordtype{B,
\lessdot} = \beta$ واخلو، او $f \colon \beta \to \tuple {B, \lessdot}$
زموږ آيزومورفيزم وټاکو. بيا:
\begin{align*}
	\alpha \in \beta&\text{ هله او يوازې هله چې }\funrestrictionto{f}{\alpha} \colon \alpha \to B_{f(\alpha)}\text{ آيزومورفيزم دے}\\
	&\text{ هله او يوازې هله چې }\ordeq{\tuple{A, <}}{\tuple{B_{f(\alpha)}, \lessdot_{f(\alpha)}}}\\
	&\text{ هله او يوازې هله چې }\ordeq{\tuple{A, <}}{\tuple{B_b, \lessdot_b}}\text{ د کوم $b \in B$ دپاره}
\end{align*}
دا د \olref[iso]{ordisounique}،
\olref[iso]{wellordinitialsegment} او
\olref[basic]{ordissetofsmallerord} له مخې دي.
\end{proof}
